import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Badge,
  Card,
  Table,
  Container,
  Row,
  Col,
} from "react-bootstrap";

/* ===============================
   CONFIG
================================ */
const API_BASE = "http://localhost:3000/api";

const ENDPOINTS = {
  stats: `${API_BASE}/dashboard-stats`,
  table: `${API_BASE}/table-data`,
  chart: `${API_BASE}/chart-data`,
};

/* ===============================
   COMPONENT
================================ */
function Dashboard() {

  /* ---------- STATE ---------- */
  const [stats, setStats] = useState({
    busStops: 0,
    cameras: "ออนไลน์",
    alerts: 0,
    users: 0,
  });

  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({
    labels: [],
    series: [[0]],
  });

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /* ---------- API FUNCTIONS ---------- */
  const fetchStats = async () => {
    const res = await fetch(ENDPOINTS.stats);
    return res.json();
  };

  const fetchTableData = async () => {
    const res = await fetch(ENDPOINTS.table);
    return res.json();
  };

  const fetchChartData = async () => {
    const res = await fetch(ENDPOINTS.chart);
    return res.json();
  };

  /* ---------- FETCH ALL DATA ---------- */
  const fetchAllData = async () => {
    setLoading(true);
    setError(null);

    try {
      const [statsJson, tableJson, chartJson] = await Promise.all([
        fetchStats(),
        fetchTableData(),
        fetchChartData(),
      ]);

      /* ---- Stats ---- */
      setStats({
        busStops: statsJson.capacity || 0,
        cameras: "ออนไลน์",
        alerts: statsJson.errors || 0,
        users: statsJson.followers || 0,
      });

      /* ---- Table ---- */
      setTableData(Array.isArray(tableJson) ? tableJson : []);

      /* ---- Chart (ป้องกันพัง) ---- */
      setChartData({
        labels: chartJson.labels || [],
        series:
          Array.isArray(chartJson.series) && chartJson.series.length > 0
            ? chartJson.series
            : [[0]],
      });

    } catch (err) {
      console.error(err);
      setError("ไม่สามารถเชื่อมต่อระบบได้");
    } finally {
      setLoading(false);
    }
  };

  /* ---------- EFFECT ---------- */
  useEffect(() => {
    fetchAllData();

    const interval = setInterval(fetchAllData, 10000);
    return () => clearInterval(interval);
  }, []);

  /* ===============================
     UI
================================ */
  return (
    <Container fluid>

      {/* ===== STATUS MESSAGE ===== */}
      {loading && <p>กำลังโหลดข้อมูล...</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      {/* ===== 1. SUMMARY CARDS ===== */}
      <Row>
        {[
          {
            title: "จุดจอดรถเมล์",
            value: `${stats.busStops} จุด`,
            icon: "nc-bus-front-12",
            color: "warning",
          },
          {
            title: "สถานะกล้อง",
            value: stats.cameras,
            icon: "nc-cctv",
            color: "success",
          },
          {
            title: "การแจ้งเตือน",
            value: `${stats.alerts} รายการ`,
            icon: "nc-bell-55",
            color: "danger",
          },
          {
            title: "ผู้ใช้งานใหม่",
            value: `+${stats.users} คน`,
            icon: "nc-single-02",
            color: "primary",
          },
        ].map((item, index) => (
          <Col lg="3" sm="6" key={index}>
            <Card className="card-stats">
              <Card.Body>
                <Row>
                  <Col xs="5">
                    <div className={`icon-big text-center icon-${item.color}`}>
                      <i className={`nc-icon ${item.icon} text-${item.color}`}></i>
                    </div>
                  </Col>
                  <Col xs="7">
                    <div className="numbers">
                      <p className="card-category">{item.title}</p>
                      <Card.Title as="h4">{item.value}</Card.Title>
                    </div>
                  </Col>
                </Row>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>

      {/* ===== 2. TABLE ===== */}
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">ตารางรายละเอียดจุดจอดรถ</Card.Title>
              <p className="card-category">ข้อมูลผู้โดยสารล่าสุด</p>
            </Card.Header>
            <Card.Body className="table-responsive">
              <Table hover striped>
                <thead>
                  <tr>
                    <th>รหัส</th>
                    <th>ชื่อสถานี</th>
                    <th>จำนวนผู้โดยสาร</th>
                    <th>สถานะ</th>
                    <th>อัปเดตล่าสุด</th>
                  </tr>
                </thead>
                <tbody>
                  {tableData.length > 0 ? (
                    tableData.map((item, index) => (
                      <tr key={item.id || index}>
                        <td>{item.id}</td>
                        <td>{item.stationName}</td>
                        <td>{item.passengerCount} คน</td>
                        <td>
                          <Badge bg={item.passengerCount > 20 ? "danger" : "success"}>
                            {item.passengerCount > 20 ? "หนาแน่น" : "ปกติ"}
                          </Badge>
                        </td>
                        <td>
                          {item.timestamp
                            ? new Date(item.timestamp).toLocaleTimeString("th-TH")
                            : "-"}
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="5" className="text-center">
                        ไม่มีข้อมูล
                      </td>
                    </tr>
                  )}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* ===== 3. CHART ===== */}
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">กราฟความหนาแน่นของผู้โดยสาร</Card.Title>
              <p className="card-category">อัปเดตทุก 10 วินาที</p>
            </Card.Header>
            <Card.Body>
              <ChartistGraph
                data={chartData}
                type="Line"
                options={{
                  low: 0,
                  height: "245px",
                  axisX: { showGrid: false },
                  lineSmooth: true,
                  showPoint: true,
                  fullWidth: true,
                  chartPadding: { right: 40 },
                }}
              />
            </Card.Body>
          </Card>
        </Col>
      </Row>

    </Container>
  );
}

export default Dashboard;
